#include "stm32l4xx_hal.h"  // STM32L4 HAL
#include "c7x10b_config.h"
#include "c7x10b.h"

// External SPI handle (defined in main.c or generated by CubeMX)
extern SPI_HandleTypeDef hspi1;  // Using SPI1

/* ============================================================================
 * Library Initialization Helper
 * ============================================================================ */

/* ============================================================================
 * Library Initialization Helper
 * ============================================================================ */

/**
 * @brief Initialize 7x10 B display for STM32
 * @note Call this after initializing SPI and GPIO in STM32CubeMX
 */
void c7x10b_init(void)
{
    // The library's init function expects pointers, but we don't use them
    // Pass NULL pointers - the actual hardware is accessed via global handles
    c7x10b_spiDriverInit(NULL, NULL);

    // Clear display on startup
    c7x10b_clearDisplay();
}
